-- Week 9: classes and objects for related data and behavior.
DO $$
DECLARE c uuid; m integer;
BEGIN
 SELECT id INTO c FROM public.courses WHERE slug='python-foundations';
 IF c IS NULL THEN RAISE EXCEPTION 'Python Foundations course must exist'; END IF;
 INSERT INTO public.modules(course_id,month_number,title,tagline,description,capstone_title,is_free,order_index,status)
 VALUES(c,9,'Classes and Objects','Week 9 · Sessions 1–5','Group related information and actions with beginner-friendly classes.','A Cookie Jar Class',false,9,'published')
 ON CONFLICT(course_id,month_number,order_index) DO UPDATE SET title=EXCLUDED.title,tagline=EXCLUDED.tagline,description=EXCLUDED.description,capstone_title=EXCLUDED.capstone_title,is_free=EXCLUDED.is_free,status=EXCLUDED.status RETURNING id INTO m;
 WITH d(n,title,analogy,body,q,opts,ans,why) AS (VALUES
 (1,'Create a Class and an Object','A design can describe many individual cookie jars.','## Goal\nTell the difference between a class and an object.\n\n## Plain explanation\nA class describes a kind of thing in a program. An object is one particular thing created from that class. `Student` can be a class; Mina and Omar can be two separate student objects. A class is useful when related information and actions belong together. It is not required for every small program.\n\n## Example\n```python\nclass Student:\n    pass\n\nmina = Student()\nomar = Student()\n```\n\nThe two variables refer to two separate objects made from the same class.','Which statement describes an object?','["One particular instance made from a class", "A Python comment", "A file mode"]'::jsonb,0,'An object is one particular instance created from a class definition.'),
 (2,'Store Information on Each Object','Each jar has its own cookie count.','## Goal\nStore instance information and understand `self`.\n\n## Plain explanation\nAn instance variable stores information on one particular object. In `self.name = name`, `self` refers to the object being initialized, and the other `name` is the value passed in. Each object can have a different value. Python supplies `self` when an instance method is called.','Why can two objects have different `self.name` values?','["Each object stores its own instance variable", "self always refers to the same object", "Class names are automatically different"]'::jsonb,0,'An instance variable belongs to one object, so separate objects can store separate values.'),
 (3,'Give an Object Methods','A jar can have actions for adding and removing cookies.','## Goal\nDefine a method that reads or changes an object.\n\n## Plain explanation\nA method is a function defined inside a class. Its first parameter is usually `self`, so it can use the current object’s information. A `deposit` method could increase the jar’s count after checking that capacity will not be exceeded. A `withdraw` method can reject an attempt to remove more cookies than are inside.','What does `self` let an instance method access?','["The current object and its stored values", "Every file on the computer", "Only the class name"]'::jsonb,0,'self identifies the current instance so its methods can read or update its attributes.'),
 (4,'Set Up and Validate an Object','Check a jar capacity when the jar is first made.','## Goal\nUse `__init__` to establish valid starting values.\n\n## Plain explanation\nPython calls `__init__` when a new object is created. It is commonly used to set the object’s starting attributes. Check the rules there: a cookie jar capacity should not be negative, for example. Raise `ValueError` with a clear message when the supplied value breaks the rule. This connects to the error handling from Week 4.','When does Python call `__init__`?','["When a new object is created", "Every time a comment is read", "Only when pytest is installed"]'::jsonb,0,'Python calls the initializer as part of creating a new instance.'),
 (5,'Compare Instance and Class Values','A student has a personal name; a class can share a common setting.','## Goal\nDistinguish information belonging to one object from information shared by a class.\n\n## Plain explanation\nAn instance variable belongs to one object, such as one learner’s name. A class variable is shared through the class, such as a common course title. A class method uses `@classmethod` and receives the class as `cls`. Introduce this only when a shared class-level operation is useful; it is more advanced than ordinary instance methods.','Which value usually belongs to one particular object?','["An instance variable such as that learner name", "A shared class constant only", "The Python version"]'::jsonb,0,'An instance variable stores information on one particular object.')
 ), ins AS (
 INSERT INTO public.sessions(module_id,session_number,title,analogy_physical,content_markdown,starter_code,hints,xp_reward,order_index,duration_minutes,quick_check)
 SELECT m,n,title,analogy,replace(body,chr(92)||'n',chr(10)),replace('class CookieJar:\n    pass\n',chr(92)||'n',chr(10)),'["Compare two separate objects.","Read self as the current object.","Add one method at a time and check its rule."]'::jsonb,50,n,15,jsonb_build_object('question',q,'options',opts) FROM d
 ON CONFLICT(module_id,session_number) DO UPDATE SET title=EXCLUDED.title,analogy_physical=EXCLUDED.analogy_physical,content_markdown=EXCLUDED.content_markdown,starter_code=EXCLUDED.starter_code,hints=EXCLUDED.hints,xp_reward=EXCLUDED.xp_reward,order_index=EXCLUDED.order_index,duration_minutes=EXCLUDED.duration_minutes,quick_check=EXCLUDED.quick_check RETURNING id,session_number
 ) INSERT INTO private.session_quick_check_answers(session_id,correct_option,explanation) SELECT ins.id,d.ans,d.why FROM ins JOIN d ON d.n=ins.session_number ON CONFLICT(session_id) DO UPDATE SET correct_option=EXCLUDED.correct_option,explanation=EXCLUDED.explanation;
END $$;
